package com.google.javascript.jscomp.type;

import com.google.common.base.Preconditions;
import com.google.javascript.Rhino.Node;
import com.google.javascript.Rhino.Token;
import com.google.javascript.jscomp.Assert;
import com.google.javascript.jscomp.CodingConvention;
import com.google.javascript.jscomp.Compiler;
import com.google.javascript.jscomp.type.JSType;
import com.google.javascript.jscomp.type.JSTypeRegistry;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import com.google.javascript.rhino.jstype.EnumElementType;
import com.google.javascript.rhino.jstype.FunctionType;
import com.google.javascript.rhino.jstype.JSType;
import com.google.javascript.rhino.jstype.JSTypeNative;
import com.google.javascript.rhino.jstype.JSTypeRegistry;
import com.google.javascript.rhino.jstype.ObjectType;
import com.google.javascript.rhino.jstype.ParameterizedType;
import com.google.javascript.rhino.jstype.StaticSlot;
import com.google.javascript.rhino.jstype.TemplateType;
import com.google.javascript.rhino.jstype.UnionType;
import com.google.javascript.rhino.jstype.Visitor;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.Assert.assertNotNull;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for getTypeIfRefinable.
 */
public class ChainableReverseAbstractInterpreter_getTypeIfRefinable_TriageGen1Test {

    private TestableInterpreter interpreter;
    private JSTypeRegistry typeRegistry;
    private CodingConvention codingConvention;

    @Mock
    private Node mockNode;
    @Mock
    private FlowScope mockScope;
    @Mock
    private StaticSlot<JSType> mockSlot;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        typeRegistry = new JSTypeRegistry();
        codingConvention = mock(CodingConvention.class);
        interpreter = new TestableInterpreter(codingConvention, typeRegistry);
    }

    /**
     * Subclass to expose protected method for testing.
     */
    private static class TestableInterpreter extends ChainableReverseAbstractInterpreter {
        public TestableInterpreter(CodingConvention convention, JSTypeRegistry typeRegistry) {
            super(convention, typeRegistry);
        }

        @Override
        public JSType getTypeIfRefinable(Node node, FlowScope scope) {
            return super.getTypeIfRefinable(node, scope);
        }

        // Mocking dependency used in the method
        @Override
        protected JSType getNativeType(JSType type) {
            return type;
        }
    }

    @Test
    public void testTokenName_SlotFound_WithTypeInSlot() {
        when(mockNode.getType()).thenReturn(Token.NAME);
        when(mockNode.getString()).thenReturn("varName");
        when(mockScope.getSlot("varName")).thenReturn(mockSlot);

        JSType expectedType = typeRegistry.getNativeType(com.google.javascript.jscomp.type.JSType.Type.STRING);
        when(mockSlot.getType()).thenReturn(expectedType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);
        assertEquals(expectedType, result);
    }

    @Test
    public void testTokenName_SlotFound_WithNullTypeInSlot_FallbackToNodeType() {
        when(mockNode.getType()).thenReturn(Token.NAME);
        when(mockNode.getString()).thenReturn("varName");
        when(mockScope.getSlot("varName")).thenReturn(mockSlot);
        when(mockSlot.getType()).thenReturn(null);

        JSType expectedType = typeRegistry.getNativeType(com.google.javascript.jscomp.type.JSType.Type.NUMBER);
        when(mockNode.getJSType()).thenReturn(expectedType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);
        assertEquals(expectedType, result);
    }

    @Test
    public void testTokenName_SlotNotFound() {
        when(mockNode.getType()).thenReturn(Token.NAME);
        when(mockNode.getString()).thenReturn("unknownVar");
        when(mockScope.getSlot("unknownVar")).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);
        assertNull(result);
    }

    @Test
    public void testTokenGetProp_QualifiedNameNull() {
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);
        assertNull(result);
    }

    @Test
    public void testTokenGetProp_SlotFound_WithTypeInSlot() {
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn("obj.prop");
        when(mockScope.getSlot("obj.prop")).thenReturn(mockSlot);

        JSType expectedType = typeRegistry.getNativeType(com.google.javascript.jscomp.type.JSType.Type.BOOLEAN);
        when(mockSlot.getType()).thenReturn(expectedType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);
        assertEquals(expectedType, result);
    }

    @Test
    public void testTokenGetProp_SlotFound_WithNullTypeInSlot_FallbackToNodeType() {
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn("obj.prop");
        when(mockScope.getSlot("obj.prop")).thenReturn(mockSlot);
        when(mockSlot.getType()).thenReturn(null);

        JSType expectedType = typeRegistry.getNativeType(com.google.javascript.jscomp.type.JSType.Type.STRING);
        when(mockNode.getJSType()).thenReturn(expectedType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);
        assertEquals(expectedType, result);
    }

    @Test
    public void testTokenGetProp_SlotNotFound_FallbackToNodeType() {
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn("obj.prop");
        when(mockScope.getSlot("obj.prop")).thenReturn(null);

        JSType expectedType = typeRegistry.getNativeType(com.google.javascript.jscomp.type.JSType.Type.NUMBER);
        when(mockNode.getJSType()).thenReturn(expectedType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);
        assertEquals(expectedType, result);
    }

    @Test
    public void testTokenGetProp_SlotNotFoundAndNodeTypeNull_FallbackToUnknown() {
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn("obj.prop");
        when(mockScope.getSlot("obj.prop")).thenReturn(null);
        when(mockNode.getJSType()).thenReturn(null);

        // In the implementation, if propVarType is null, it returns getNativeType(UNKNOWN_TYPE)
        // Note: UNKNOWN_TYPE is likely a constant in the parent class. 
        // Since we mocked getNativeType in TestableInterpreter, it returns the arg.
        JSType unknownType = typeRegistry.getNativeType(com.google.javascript.jscomp.type.JSType.Type.UNKNOWN);
        // Note: The code uses UNKNOWN_TYPE which is a field in the class. 
        // For the purpose of this test, we assume the logic flow reaches the final null check.

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);
        // Since we cannot easily access the private UNKNOWN_TYPE constant here without reflection, 
        // we verify that the logic flows through the conditional.
        assertNotNull(result);
    }

    @Test
    public void testOtherTokenType() {
        when(mockNode.getType()).thenReturn(Token.ASSIGN);
        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);
        assertNull(result);
    }
}
